-- Generated by graph/tools/build_jobalio_validation_worksets.py from sealed SQL005.
-- Group only JOB-ALIO JSONB conflict fields; preserve typed issue bags.
BEGIN;
DO $guard$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE
  p.oid='ingestion.source_graph_scoped_validation_issue(text)'::regprocedure
  AND md5(p.prosrc) IN ('bad3ac1508bc564c02cc593a022e4c44','dda5d9e3b23d720700b4a4fe55d69918')
  AND p.provolatile='s' AND p.proparallel='u' AND NOT p.proisstrict
  AND NOT p.prosecdef AND NOT p.proleakproof AND p.proretset
  AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='sql')
  AND p.prorettype='record'::regtype AND p.pronargdefaults=0
  AND p.proallargtypes=ARRAY[25,25,25,25]::oid[]
  AND p.proargnames=ARRAY['jobs','run_id','issue','location']::text[]
  AND p.proargmodes=ARRAY['i','t','t','t']::"char"[]
  AND p.proconfig=ARRAY['jit=off']::text[]) THEN
  RAISE EXCEPTION 'SOURCE_GRAPH_JOBALIO_WORKSET_BASELINE_DRIFT';
 END IF;
END $guard$;

CREATE OR REPLACE FUNCTION ingestion.source_graph_scoped_validation_issue(jobs text)
RETURNS TABLE(run_id text,issue text,location text)
LANGUAGE sql STABLE SET jit=off AS $$
WITH
runs AS MATERIALIZED (SELECT * FROM ingestion.run WHERE run_id=jobs),
partitions AS MATERIALIZED (SELECT * FROM ingestion.partition WHERE run_id=jobs),
documents AS MATERIALIZED (SELECT * FROM ingestion.document WHERE run_id=jobs),
records AS MATERIALIZED (SELECT * FROM ingestion.record WHERE run_id=jobs),
dependencies AS MATERIALIZED (SELECT * FROM ingestion.dependency WHERE run_id=jobs),
rejected AS MATERIALIZED (SELECT * FROM ingestion.rejected_row WHERE run_id=jobs),
record_rows AS MATERIALIZED (SELECT run_id,document_id,count(*) AS rows FROM records
 GROUP BY run_id,document_id),
rejected_rows AS MATERIALIZED (SELECT run_id,document_id,count(*) AS rows FROM rejected
 GROUP BY run_id,document_id),
selected AS MATERIALIZED (
    SELECT d.* FROM documents d WHERE d.selected
), facts AS MATERIALIZED (
    SELECT r.run_id,r.document_id,r.locator,r.source_record_id,r.normalized,d.partition_id
    FROM records r JOIN selected d USING (run_id, document_id)
), document_counts AS (SELECT run_id,partition_id,count(document_id) AS documents,
 min(page_no) AS first_page,max(page_no) AS last_page FROM selected
 GROUP BY run_id,partition_id),
partition_counts AS (SELECT p.*,coalesce(c.documents,0) AS documents,
 c.first_page,c.last_page FROM partitions p
 LEFT JOIN document_counts c USING(run_id,partition_id)), pairs AS (
    SELECT f.run_id, f.normalized->>'posting_id' AS posting_id,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'list') AS lists,
           count(*) FILTER (WHERE f.normalized->>'representation' = 'detail') AS details
    FROM facts f JOIN runs u USING (run_id)
    WHERE u.source_id = 'job_alio'
    GROUP BY f.run_id, f.normalized->>'posting_id'
), nara_pairs AS (
    SELECT f.run_id,f.normalized->>'posting_id' AS posting_id,
      count(*) FILTER(WHERE f.normalized->>'representation'='list') AS lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='list' AND coalesce((f.normalized->>'ongoing')::boolean,false)) AS active_lists,
      count(*) FILTER(WHERE f.normalized->>'representation'='detail') AS details,
      count(*) FILTER(WHERE f.normalized->>'representation'='positions') AS positions,
      count(*) FILTER(WHERE f.normalized->>'representation'='files') AS files
    FROM facts f JOIN runs u USING(run_id)
    WHERE u.source_id='nara_job'
    GROUP BY f.run_id,f.normalized->>'posting_id'
), nara_conflict_facts AS MATERIALIZED (
 SELECT f.run_id,f.normalized->>'posting_id' AS posting_id,
 f.normalized->>'representation' AS representation,f.normalized->>'title' AS title
 FROM facts f JOIN runs u USING(run_id) WHERE u.source_id='nara_job'
), nara_conflict_groups AS (
 SELECT run_id,posting_id,
 array_agg(title) FILTER(WHERE representation='list') AS list_titles,
 array_agg(title) FILTER(WHERE representation='detail') AS detail_titles
 FROM nara_conflict_facts WHERE posting_id IS NOT NULL
 GROUP BY run_id,posting_id
), jobalio_conflict_facts AS MATERIALIZED (
 SELECT f.run_id,f.normalized->>'posting_id' AS posting_id,
 f.normalized->>'representation' AS representation,
 f.normalized->'title' AS title,f.normalized->'organization_code' AS organization,
 f.normalized->'date_posted' AS date_posted,f.normalized->'closing_date' AS closing_date,
 f.normalized->'ongoing' AS ongoing,f.normalized->>'ongoing' IS NOT NULL AS ongoing_present
 FROM facts f JOIN runs u USING(run_id) WHERE u.source_id='job_alio'
), jobalio_conflict_groups AS (
 SELECT run_id,posting_id,
 array_agg(title) FILTER(WHERE representation='list') AS list_titles,
 array_agg(organization) FILTER(WHERE representation='list') AS list_organizations,
 array_agg(date_posted) FILTER(WHERE representation='list') AS list_dates,
 array_agg(closing_date) FILTER(WHERE representation='list') AS list_closing_dates,
 array_agg(ongoing) FILTER(WHERE representation='list') AS list_ongoing,
 array_agg(title) FILTER(WHERE representation='detail') AS detail_titles,
 array_agg(organization) FILTER(WHERE representation='detail') AS detail_organizations,
 array_agg(date_posted) FILTER(WHERE representation='detail') AS detail_dates,
 array_agg(closing_date) FILTER(WHERE representation='detail') AS detail_closing_dates,
 array_agg(ongoing) FILTER(WHERE representation='detail') AS detail_ongoing,
 array_agg(ongoing_present) FILTER(WHERE representation='detail') AS detail_ongoing_present
 FROM jobalio_conflict_facts WHERE posting_id IS NOT NULL
 GROUP BY run_id,posting_id
)
SELECT u.run_id, 'SMOKE_NOT_FULL'::text AS issue, ''::text AS location
FROM runs u WHERE u.mode = 'SMOKE'
UNION ALL
SELECT u.run_id, 'NO_PARTITIONS', '' FROM runs u
WHERE NOT EXISTS (SELECT 1 FROM partitions p WHERE p.run_id = u.run_id)
UNION ALL
SELECT d.run_id, 'DEPENDENCY_NOT_READY_OR_WRONG_SOURCE', d.input_source_id
FROM dependencies d JOIN ingestion.run u ON u.run_id = d.input_run_id
WHERE u.state <> 'READY' OR u.mode = 'SMOKE' OR u.source_id <> d.input_source_id
UNION ALL
SELECT u.run_id, 'MISSING_DEPENDENCY', u.source_id
FROM runs u
WHERE u.source_id IN ('ncs_qualification', 'qnet_schedule', 'job_alio')
  AND NOT EXISTS (
      SELECT 1 FROM dependencies d WHERE d.run_id = u.run_id
      AND d.input_source_id = CASE u.source_id
          WHEN 'ncs_qualification' THEN 'ncs_competency'
          WHEN 'qnet_schedule' THEN 'ncs_qualification'
          WHEN 'job_alio' THEN 'alio_organization' END)
UNION ALL
SELECT run_id, 'PARTITION_INCOMPLETE', partition_id FROM partition_counts
WHERE expected_total IS NULL
   OR (kind = 'PAGED' AND (documents <> CASE WHEN expected_total = 0 THEN 2
                    ELSE ceil(expected_total::numeric / page_size)::integer END
       OR first_page <> 1
       OR last_page <> greatest(1, ceil(expected_total::numeric / page_size)::integer)))
   OR (kind <> 'PAGED' AND (documents <> 1 OR first_page <> 1 OR last_page <> 1))
UNION ALL
SELECT d.run_id, 'DOCUMENT_METADATA_OR_FILE_NOT_VERIFIED', d.document_id
FROM selected d
JOIN partitions p USING (run_id, partition_id)
JOIN runs u USING (run_id)
WHERE (coalesce(to_jsonb(d)->>'transport','HTTP')='HTTP' AND d.http_status IS DISTINCT FROM 200)
   OR (coalesce(to_jsonb(d)->>'transport','HTTP')='LOCAL_FILE' AND
       (u.source_id<>'jobkorea' OR d.http_status IS NOT NULL OR d.provider_result IS NOT NULL))
   OR d.byte_length = 0 OR d.verified_at IS NULL
   OR d.item_count IS NULL OR d.effective_page IS DISTINCT FROM d.page_no
   OR (p.kind = 'PAGED' AND (
          d.declared_total IS DISTINCT FROM p.expected_total
       OR d.effective_page_size IS DISTINCT FROM p.page_size
       OR d.item_count IS DISTINCT FROM
            greatest(0, least(p.page_size, p.expected_total - (d.page_no - 1) * p.page_size))
       OR (p.expected_total > 0 AND d.confirmation_no <> 0)
       OR (p.expected_total = 0 AND d.page_no <> 1)))
   OR (p.kind = 'DETAIL' AND (d.item_count <> 1 OR d.confirmation_no <> 0))
   OR (p.kind = 'FILE' AND (d.item_count IS DISTINCT FROM p.expected_total
                          OR d.item_count = 0 OR d.confirmation_no <> 0))
   OR (u.source_id IN ('alio_organization', 'job_alio')
       AND d.provider_result IS DISTINCT FROM '200')
   OR (u.source_id IN ('ncs_qualification', 'qnet_schedule')
       AND (d.provider_result IS NULL OR d.provider_result NOT IN ('00', '0', 'SUCCESS')))
UNION ALL
SELECT d.run_id, 'ROW_COUNT_MISMATCH', d.document_id FROM selected d
LEFT JOIN record_rows r USING(run_id,document_id)
LEFT JOIN rejected_rows e USING(run_id,document_id)
WHERE d.item_count IS DISTINCT FROM coalesce(r.rows,0)+coalesce(e.rows,0)
UNION ALL
SELECT e.run_id, 'REJECTED_ROW', e.document_id || ':' || e.locator
FROM rejected e JOIN selected d USING (run_id, document_id)
UNION ALL
SELECT run_id, 'DUPLICATE_SOURCE_ID', source_record_id FROM facts
GROUP BY run_id, source_record_id HAVING count(*) <> 1
UNION ALL
SELECT f.run_id, 'WRONG_RECORD_KIND', f.document_id || ':' || f.locator
FROM facts f JOIN runs u USING (run_id)
WHERE f.normalized->>'kind' IS DISTINCT FROM CASE u.source_id
    WHEN 'alio_organization' THEN 'Organization' WHEN 'job_alio' THEN 'JobPosting'
    WHEN 'nara_job' THEN 'JobPosting' WHEN 'jobkorea' THEN 'JobPosting'
    WHEN 'ncs_career_path' THEN 'CareerPath' WHEN 'ncs_competency' THEN 'Competency'
    WHEN 'ncs_qualification' THEN 'QualificationMapping' WHEN 'qnet_schedule' THEN 'ExamSession' END
UNION ALL
SELECT f.run_id, 'PARTITION_IDENTITY_MISMATCH', f.document_id || ':' || f.locator
FROM facts f JOIN runs u USING (run_id)
WHERE (u.source_id = 'ncs_qualification'
       AND f.partition_id IS DISTINCT FROM 'ncs-' || (f.normalized->>'competency_code'))
   OR (u.source_id = 'qnet_schedule'
       AND f.partition_id IS DISTINCT FROM 'year-' || (f.normalized->>'year')
                                           || '-item-' || (f.normalized->>'qualification_code'))
   OR (u.source_id = 'job_alio' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' = 'detail'
           AND f.partition_id IS DISTINCT FROM 'detail-' || (f.normalized->>'posting_id'))))
   OR (u.source_id = 'nara_job' AND (
       (f.normalized->>'representation' = 'list' AND f.partition_id <> 'index')
       OR (f.normalized->>'representation' IN ('detail','positions','files')
           AND f.partition_id IS DISTINCT FROM (f.normalized->>'representation') || '-' || (f.normalized->>'posting_id'))))
UNION ALL
SELECT run_id, 'POSTING_PAIR_MISSING_OR_DUPLICATED', posting_id FROM pairs
WHERE lists <> 1 OR details <> 1
UNION ALL
SELECT run_id,'NARA_ACTIVE_RESOURCE_MISSING_OR_DUPLICATED',posting_id FROM nara_pairs
WHERE lists<>1 OR (active_lists=1 AND (details<>1 OR positions<>1 OR files<>1))
   OR (active_lists=0 AND (details<>0 OR positions<>0 OR files<>0))
UNION ALL
SELECT g.run_id,'NARA_POSTING_CONFLICT',g.posting_id
FROM nara_conflict_groups g
CROSS JOIN LATERAL unnest(g.list_titles) l(title)
CROSS JOIN LATERAL unnest(g.detail_titles) d(title)
WHERE nullif(d.title,'') IS NOT NULL AND l.title IS DISTINCT FROM d.title
UNION ALL
SELECT g.run_id, 'POSTING_PAIR_CONFLICT', g.posting_id
FROM jobalio_conflict_groups g
CROSS JOIN LATERAL unnest(g.list_titles,g.list_organizations,g.list_dates,
 g.list_closing_dates,g.list_ongoing) l(title,organization,date_posted,closing_date,ongoing)
CROSS JOIN LATERAL unnest(g.detail_titles,g.detail_organizations,g.detail_dates,
 g.detail_closing_dates,g.detail_ongoing,g.detail_ongoing_present)
 d(title,organization,date_posted,closing_date,ongoing,ongoing_present)
WHERE l.title IS DISTINCT FROM d.title
 OR l.organization IS DISTINCT FROM d.organization
 OR l.date_posted IS DISTINCT FROM d.date_posted
 OR l.closing_date IS DISTINCT FROM d.closing_date
 OR (d.ongoing_present AND l.ongoing IS DISTINCT FROM d.ongoing)
UNION ALL
SELECT run_id,issue,location FROM ingestion.source_graph_local_validation_issue(jobs)
$$;
COMMIT;
